[{"order":1,"type":"heading","text":"Flask: Routing, Templates, and Forms"},{"order":2,"type":"paragraph","text":"Flask is a micro web framework written in Python. It is classified as a microframework because it does not require particular tools or libraries. Flask allows you to build web applications quickly and easily. This tutorial covers routing, templates, and forms in Flask."},{"order":3,"type":"subheading","text":"Routing"},{"order":4,"type":"paragraph","text":"Routing refers to determining how an application responds to a client request to a particular URL. In Flask, you use the `@app.route` decorator to bind a function to a URL."},{"order":5,"type":"code","text":"from flask import Flask

app = Flask(__name__)

@app.route('/')
def hello_world():
    return 'Hello, World!'

if __name__ == '__main__':
    app.run(debug=True)"},{"order":6,"type":"paragraph","text":"In this example, the `hello_world` function is bound to the root URL ('/'). When a user visits the root URL, the function returns 'Hello, World!'."},{"order":7,"type":"subheading","text":"Dynamic Routing"},{"order":8,"type":"paragraph","text":"Flask also supports dynamic routing, where you can pass variables in the URL. You can define these variables using `<variable_name>` in the route."},{"order":9,"type":"code","text":"@app.route('/user/<username>')
def show_user_profile(username):
    # show the user profile for that user
    return f'User {username}'

@app.route('/post/<int:post_id>')
def show_post(post_id):
    # show the post with the given id, the id is an integer
    return f'Post ID: {post_id}'"},{"order":10,"type":"paragraph","text":"In the first example, `<username>` captures any string after `/user/`. In the second example, `<int:post_id>` captures an integer after `/post/` and converts it to an integer."},{"order":11,"type":"subheading","text":"Templates"},{"order":12,"type":"paragraph","text":"Templates allow you to separate the presentation layer from the application logic. Flask uses Jinja2 as its template engine. Templates are stored in a 'templates' folder in the same directory as your Flask application."},{"order":13,"type":"code","text":"<!-- templates/index.html -->
<!DOCTYPE html>
<html>
<head>
    <title>{{ title }}</title>
</head>
<body>
    <h1>Hello, {{ name }}!</h1>
</body>
</html>"},{"order":14,"type":"code","text":"from flask import Flask, render_template

app = Flask(__name__)

@app.route('/hello/<name>')
def hello(name):
    return render_template('index.html', name=name, title='Hello Page')

if __name__ == '__main__':
    app.run(debug=True)"},{"order":15,"type":"paragraph","text":"The `render_template` function renders the specified template and passes the provided variables to the template. In this example, the `name` and `title` variables are passed to the 'index.html' template."},{"order":16,"type":"subheading","text":"Forms"},{"order":17,"type":"paragraph","text":"Flask-WTF is a library that simplifies working with forms in Flask. It provides CSRF protection, form rendering, and validation."},{"order":18,"type":"code","text":"from flask import Flask, render_template, request, flash, redirect, url_for
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Email, EqualTo
from flask_bootstrap import Bootstrap

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your_secret_key'
Bootstrap(app)

class RegistrationForm(FlaskForm):
    email = StringField('Email', validators=[DataRequired(), Email()])
    password = PasswordField('Password', validators=[DataRequired()])
    confirm_password = PasswordField('Confirm Password', validators=[DataRequired(), EqualTo('password')])
    submit = SubmitField('Register')

@app.route('/register', methods=['GET', 'POST'])
def register():
    form = RegistrationForm()
    if form.validate_on_submit():
        flash(f'Account created for {form.email.data}!', 'success')
        return redirect(url_for('hello_world'))
    return render_template('register.html', title='Register', form=form)

@app.route('/')
def hello_world():
    return 'Hello, World!'

if __name__ == '__main__':
    app.run(debug=True)"},{"order":19,"type":"code","text":"<!-- templates/register.html -->
{% extends "bootstrap/base.html" %}
{% block content %}
<div class="container">
    <h1>Register</h1>
    <form method="POST" action="">
        {{ form.hidden_tag() }}
        <div class="form-group">
            {{ form.email.label }}<br>
            {{ form.email(class="form-control") }}
            {% for error in form.email.errors %}
            <span style="color: red;">[{{ error }}]</span>
            {% endfor %}
        </div>
        <div class="form-group">
            {{ form.password.label }}<br>
            {{ form.password(class="form-control") }}
            {% for error in form.password.errors %}
            <span style="color: red;">[{{ error }}]</span>
            {% endfor %}
        </div>
        <div class="form-group">
            {{ form.confirm_password.label }}<br>
            {{ form.confirm_password(class="form-control") }}
            {% for error in form.confirm_password.errors %}
            <span style="color: red;">[{{ error }}]</span>
            {% endfor %}
        </div>
        {{ form.submit(class="btn btn-primary") }}
    </form>
</div>
{% endblock %}"},{"order":20,"type":"paragraph","text":"This example demonstrates a registration form with email, password, and confirm password fields. The `RegistrationForm` class defines the form fields and their validators. The `register` route handles the form submission and validation. Flask-Bootstrap is used for styling the form."},{"order":21,"type":"paragraph","text":"Remember to install the necessary packages: `pip install Flask Flask-WTF WTForms flask_bootstrap`"}]
